#!/bin/sh
set -eu
runner=$1
case "$runner" in /*) ;; *) runner="$PWD/$runner";; esac
if [ "$#" -gt 1 ]; then
    OCAMLCC_QBE=$2
    case "$OCAMLCC_QBE" in /*) ;; *) OCAMLCC_QBE="$PWD/$OCAMLCC_QBE";; esac
    export OCAMLCC_QBE
fi
scratch=$(mktemp -d)
trap 'rm -rf "$scratch"' EXIT
export OCPKG_CACHE="$scratch/cache"
cd "$scratch"
mkdir -p src a b
printf 'let value = 17\n' > a/util.ml
printf 'val value : int\n' > a/util.mli
printf 'let next () = Util.value + 1\n' > a/more.ml
printf 'let value = 24\n' > b/util.ml
# The two digests are generated by the compatible SHA-256 tree codec.
a_tree=6f03b5233de5eb457bff61dcb0ae84abe7b627d1edda058436890d297415fc2e
b_tree=bfa748f2d0d745ba3fc46e792f4463d28213efa029840a4ff8eb0d75071d8a65
cat > fixture.snap <<SNAP
schema 1
pkg alpha 1
  local a
  tree $a_tree
  wrapped Alpha
  file util.ml <= util.ml
  file util.mli <= util.mli
  file more.ml <= more.ml
pkg beta 1
  local b
  tree $b_tree
  wrapped Beta
  file util.ml <= util.ml
SNAP
cat > ocpkg.mod <<'MOD'
module test-wrap
entry src/main.ml
source src
snapshot fixture.snap
require (
  alpha 1
  beta 1
)
MOD
cat > src/main.ml <<'ML'
let () = Printf.printf "%d\n" (Alpha.More.next () + Beta.Util.value)
ML
"$runner" vendor --offline
test "$("$runner" run)" = 42
find "$OCPKG_CACHE/pkg" -name '*.a.opt' | sort > summaries
test "$(wc -l < summaries)" -eq 2
cat > src/main.ml <<'ML'
let () = Printf.printf "%d\n" Alpha__Util.value
ML
if "$runner" build > rejected.out 2> rejected.log; then
    echo 'wrapped private unit was visible' >&2
    exit 1
fi
grep -q 'Unbound module Alpha__Util' rejected.log
cp -p vendor/alpha/util.ml original
printf 'let value = 12\n' > vendor/alpha/util.ml
touch -r original vendor/alpha/util.ml
if "$runner" build -v > tampered.out 2> tampered.log; then
    exit 1
fi
grep -q 'vendored source changed' tampered.log
if grep -q '^compile ' tampered.log; then
    exit 1
fi
echo 'wrapped package isolation: PASS'
